// Import of required libraries
import { test, expect, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';
import { fillNewOwnerForm, fillOwnerPhoneNumber } from './skyrampUtils';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:4200");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(113000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    const pageErrors: string[] = [];
    page.on('pageerror', (e) => pageErrors.push(e.message));

    await page.goto(baseUrl);
    await page.getByRole("button", { name: "Owners" }).click();
    await page.getByRole("link", { name: "Add New" }).click();

    await fillNewOwnerForm(page, "Ada", "Lovelace", "5 Analytical Way", "Madison");
    await fillOwnerPhoneNumber(page, "abcdef");

    await expect(page.getByText("Phone number only accepts")).toContainText("Phone number only accepts digits");
    await expect(page.locator("#phoneNumber")).toHaveValue("abcdef");
    await expect(page.getByRole("button", { name: "Add Owner" })).toBeDisabled();

    await page.getByRole("textbox", { name: "Phone" }).fill("6085551234");

    await expect(page.locator("#phoneNumber")).toHaveValue("6085551234");
    await expect(page.getByText("Phone number only accepts")).toHaveCount(0);
    await expect(page.getByRole("button", { name: "Add Owner" })).toBeEnabled();

    expect(pageErrors).toHaveLength(0);
});
